"""Freeze East whole-collapse request after selected/guide/master inspection."""
from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'character/marsh-east-collapse-material-v1'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
    sources=BASE/'sources';guide=json.loads((sources/'guide-provenance.json').read_text())
    for r in guide['primarySourceFrames']+guide['guideSourceFrames']:assert sha(ROOT/r['path'])==r['sha256']
    prompt='''Create a transparent pixel-art animation SOURCE SHEET of SIX COMPLETE clearly separated figures in ONE horizontal row with wide transparent gutters. This is Marsh, the exact EAST/right-facing adult male android from reference1. Reference1 selected East idle/gait is PRIMARY for fitted adult build, exact head/torso/limb proportions, camera, drawing density and warm matte ivory/sage material grade. Reference2 is ONLY a whole-pose mechanical collapse motion guide: its enlarged heads, stockier upper body or dark boot uppers must not become the anatomical master. Reference3 original East standing master controls facial identity, visible temple hardware, blond swept hair, harness/chest equipment and fitted ivory/sage clothing. The magenta master background must NOT appear.

Figures1-5 form a dry controlled shutdown in elevated side perspective, ALWAYS facing RIGHT. 1 Very slight knee softening and mild forward torso dip, complete arms naturally flex; 2 lower crouch with weight descending over feet, torso leaning forward; 3 knees touch floor, complete legs fold naturally behind to LEFT, hands prepare forward support; 4 chest lowers, complete connected forearms brace on floor in front to RIGHT; 5 fully prone body extends horizontally, boots and legs to LEFT, head and connected forearms to RIGHT. Match the guide's elevated East camera and projected floor line. Preserve the adult narrow fitted torso, unchanged anatomical head/equipment size and natural foreshortening through every pose. No front/rear turning, no mirrored figure or arbitrary new camera. Boots remain warm IVORY upper guards with dark matte soles; do not replace the whole boot with black. Full dark gloves, slate flexible joints, sage shoulder/pouch details, blond hair and visible temple plate retain exact selected material relationships. Complete connected shoulders/elbows/hands, knees/ankles/feet within each cell. No added tools, backpack, helmet or extra limbs.

Figure6 is exact neutral standing East ruler from reference1. Selected standing occupies32pixels wide by147pixels high in184canvas with declared148standingHeight and pivot92/172; this narrow SIDE silhouette is intentional, not the55pixel rear silhouette. ALL six figures share ONE drawing scale calibrated by this neutral. Do not enlarge lowered poses to standing height, thicken heads/shoulders, or force articulated horizontal widths to32. Preserve master-sized adult anatomy as crouch/prone silhouette widens naturally. Final body length must follow complete adult anatomy at this scale, not a stretched old rectangle.

Crisp restrained warm pixel clusters, muted matte ivory panels/fabric, sage shoulders and belt pouches, slate joint bands, dark gloves and soles. No glossy/cyan highlights, cold blue grade or broad new outlines. Consistent head and suit detail scale throughout. This is DRY shutdown: no coolant, blood, puddles, smoke or sparks. Actual transparent background; no floor plane, cast shadow, text, labels or gutters printed. Draw six COMPLETE whole figures, never patched limb pieces.'''
    path=sources/'collapse-01.prompt.txt';assert not path.exists();path.write_text(prompt+'\n',encoding='utf-8')
    refs=[sources/'selected-east-idle-gait.png',sources/'collapse-pose-guide.png',ROOT/'character/marsh-motion-polish-v1/sources/east-standing-identity-01.png']
    request={'normalAdmission':False,'status':'frozen whole East request before generation','promptSha256':sha(path),'orderedReferences':[{'path':p.relative_to(ROOT).as_posix(),'sha256':sha(p)} for p in refs],**{k:guide[k] for k in ['primarySourceFrames','guideSourceFrames','selectedIdleOccupiedSize','selectedMetadata']},'transparentBackground':True,'sheetGrid':[6,1],'contract':{'canvas':[184,184],'pivot':[92,172],'standingHeight':148,'durationsMs':[180]*6,'loop':False},'constraints':'Complete right-facing poses at one selected147-occupied neutral calibration. No per-pose fit, anatomy patch, mirroring or palette mapping.'}
    (sources/'collapse-01.request.json').write_text(json.dumps(request,indent=2)+'\n')
    print('Frozen East exact prompt and ordered references after visual inspection.')
if __name__=='__main__':main()
